from ros.translate import InstructionTranslator
primitive_actions =[
    "NAVIGATE_TO banana|-02.86|+00.70|-00.52", 
    "GRASP banana|-02.86|+00.70|-00.52",
    "NAVIGATE_TO cooker|-01.92|+00.44|+02.03|cookerBasin",
    "PLACE_INSIDE cooker|-01.92|+00.44|+02.03|cookerBasin",
    "NAVIGATE_TO banana|-02.86|+00.70|-00.52", 
    "GRASP banana|-02.86|+00.70|-00.52",
]

# init_ros_communication()
# try:
for primitive_action in primitive_actions:
    translated_primitive_action = InstructionTranslator.translate(
        instruction=primitive_action
    )
    print(translated_primitive_action)
